"""Save the 19 original artwork briefs. Does not alter any artwork or runtime file."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent
REPO = ROOT.parents[2]
if any(ROOT.glob('*/*.png.generation.json')):
    raise SystemExit('Artwork already exists. Keep its exact prompts and records; do not overwrite concepts.json.')
OLD = ROOT.parent / 'heroine-concepts-v1-20261008'
OLD_REL = '../heroine-concepts-v1-20261008/'
old_concepts = json.loads((OLD / 'concepts.json').read_text())['concepts']
identities = {}
for char in ['tsumugi', 'mashiro', 'minto', 'ageha', 'rin']:
    concept = next(c for c in old_concepts if c['character'] == char and c['shisha'])
    identities[char] = (OLD / concept['prompt']).read_text().split('IDENTITY: ')[1].split('\n\nSCENE:')[0]
identities['samechan'] = '''Samechan, called Same-chan / Shark girl, ADULT woman age 20 with ordinary adult proportions. Adopted BLACK hair with DEEP BLUE to lighter-blue INNER layers, bright BLUE eyes, cute slightly half-lidded gaze and small pointed shark teeth when smiling. Black/ivory/pale-blue STREET SISTER outfit: nun-coif-like black hood with ivory border and blue shark fins, cross details, oversized street jacket, ivory top, black pleated short skirt with pale-blue hem, belts/chains and dark stockings. Use her current adopted face and costume, not the earlier all-blue-haired design. Koro is one BLUE SHARK PLUSH with white belly, black eyes, toothy grin, SMALL GOLD CROWN and blue bow with tiny gold star. Koro is a toy, not a live shark. She loves shark movies and is serious about making a comfortable shop, not a tournament rival.'''

common = '''Create ONE original scene artwork for the right side of a Japanese visual-novel title screen. Opaque PNG, portrait 2:3, preferably 1024x1536. No collage/panels. Reference 1 is the adopted ADULT heroine identity. Reference 2 is the currently adopted Mashiro title image for PIXEL RENDERING ONLY. The owner wants visibly MORE pixel/dot texture than the previous concepts: crisp small square color clusters, slightly stepped edges and delicate ordered dithering in shadows, like a detailed 384x576 pixel painting enlarged cleanly. Keep pleasant anime eyes/faces and hand details readable, with moderate pixel texture throughout. Do NOT deliver smooth airbrushed anime or merely add photo grain; no photographic/3D look, motion blur or huge block pixels.
Reference 2 is NOT a location, architecture, color palette or layout template. DO NOT copy its bookshelves, ivy, stained-glass lanterns, medieval city, antique chair or amber-library background into every picture. Follow this brief's specific room, location, light and palette. Exterior scenes are contemporary JAPAN, never European castles/cathedrals/stone old towns.
Preserve adopted hair, face, eyes, key clothes and adult proportions. New natural pose, only this heroine visible, no protagonist face. Face around x50–65% y20–35%, comfortable head/hand margins, focal props inside middle/right 80% above 85% height. Leftmost 20% can later fade under title UI. Exactly two arms, natural hands, no floating parts. NO words, numbers, typography, labels, UI, logos, small brand emblems or watermarks in the artwork. Scene names are outside the image in the gallery.
'''
hardware = '''Use actual manufacturer product photos after identity/style refs to reproduce the specified real body/bowl/heat-control geometry, not the wrong exposed-coal head in the old title image. Conventional hookahs have a tray BELOW a separately fitted bowl, small top metal post, sealed bowl neck. One rigid vertical axis, no cup-shaped integral stem. Exactly ONE mouthpiece in her hand, ONE continuous silicone/leather hose from its lower connector to the actual BODY/MANIFOLD hose port near the vase; never bowl/tray/water surface. Hose is clearly traceable across the FRONT of her lap, not broken or disappearing into knees; no unused second mouthpiece on the table or branching hoses. No floating coals, flames or smoke from water vessel. If transparent, water is just above downstem end. Complete equipment visible inside image margins, heat-control stack readable, equipment smaller than her upper body. Remove ALL printed/embossed brand words/emblems in reference photos. Render in the same pixel-art style.
'''
