result = []
style = (REPO / 'tools/bg_prompts.txt').read_text().splitlines()[2]
for char, variant, label, shisha, scene in scenes:
    (ROOT / char).mkdir(exist_ok=True)
    identity = 'references/samechan-adopted-normal.png' if char == 'samechan' else OLD_REL+'references/'+char+'-adopted-normal.png'
    refs = [identity, OLD_REL+'references/title-style.png']
    if char == 'minto' and variant.startswith(('03-', '04-')):
        refs.append(OLD_REL+'references/minto-private.png')
    model = None
    specific = 'No hookah/hose/charcoal or tobacco apparatus anywhere in this non-shisha scene.'
    if shisha:
        model, equipment_refs, description = devices[char]
        refs.extend(equipment_refs)
        specific = hardware+'\nSPECIFIC REAL EQUIPMENT: '+description
    source = f'{char}/{variant}.png'
    prompt = f'{char}/{variant}.prompt.txt'
    text = style+'\n\n'+common+'\nIDENTITY: '+identities[char]+'\n\nSCENE: '+scene+'\n\n'+specific+'\n\nProposed preserved source: '+str(ROOT.relative_to(REPO))+'/'+source+'\n'
    (ROOT / prompt).write_text(text)
    result.append(dict(id=char+'-'+variant,character=char,label=label,shisha=shisha,hardware_reference_model=model,source=source,prompt=prompt,references=refs,runtime_installed=False,status='planned'))
(ROOT / 'concepts.json').write_text(json.dumps(dict(tool='image_gen.imagegen',base_sha='fa3d7fd1f7c2e3e6be2815a9a7f9220390109b05',purpose='TA01–12: 6 heroines x3 plus Minto intermediate =19; varied real equipment/backgrounds and adopted-title pixel texture',previous_comparison_folder='../heroine-concepts-v1-20261008',transparent_background=False,concepts=result),ensure_ascii=False,indent=2)+'\n')
print('Saved', len(result), 'independent scene prompts')
